export const BODY: string = "\n<p>ثلاثة أرقام تصف كل صورة، والناس تخلط بينها طوال الوقت: الأبعاد والدقة وحجم الملف تبدو مرتبطة، لكن كل منها يقيس شيئًا مختلفًا.</p>\n<p>الخلط يسبب أخطاء حقيقية: الناس تشتري كاميرا بميغابكسلات كثيرة وتتساءل لماذا تبدو الطباعة ناعمة، أو تضغط ملفًا وتتساءل لماذا لا يرفع مع ذلك.</p>\n<p>يفكك هذا المقال الأرقام الثلاثة ويُظهر كيف ترتبط ويشرح أيها يهم للويب والطباعة ووسائل التواصل الاجتماعي.</p>\n<h2 id=\"three-different-numbers\">ثلاثة أرقام وثلاثة معانٍ</h2>\n<p>الأبعاد هي العرض والارتفاع بالبكسلات، مثل 1920 في 1080: تصف كم بكسلًا تحتوي الصورة، ولا شيء أكثر.</p>\n<p>الدقة هي كثافة تلك البكسلات، وتُعطى عادة كـDPI أو PPI: تقول كم بكسلًا يناسب بوصة عندما تُطبع الصورة أو تُعرض. وحجم الملف هو وزن الصورة على القرص، عادة بالكيلوبايت أو الميغابايت: يقول كم تخزين يحتاج الملف وكم يستغرق تنزيله.</p>\n<p>وكل رقم قد يتغير دون أن يتحرك الآخران: تستطيع تصغير ملف دون لمس أبعاده، وتستطيع تغيير DPI دون لمس بكسل واحد.</p>\n<h2 id=\"dimensions-explained\">الأبعاد: عدد البكسلات</h2>\n<p>الأبعاد هي أكثر الأرقام الثلاثة واقعية: صورة 4000 في 3000 تحتوي 12 مليون بكسل، مرتبة في 4000 عمود و3000 صف.</p>\n<p>الأبعاد تقرر كم حجم تستطيع صورة أن تظهر على الشاشة دون مد: صورة 400 بكسل معروضة بعرض 1200 بكسل يجب أن تخترع ثلثي بكسلاتها، والاختراع يبدو ناعمًا دائمًا. والأبعاد تقرر أيضًا أقصى حجم طباعة: اقسم العرض بالبكسلات على DPI الطباعة للحصول على العرض القابل للطباعة بالبوصات، فبكسلات أكثر تعني طباعة أكبر.</p>\n<p>وعندما ترفض منصة صورة لأنها صغيرة جدًا، فهي تراجع الأبعاد دائمًا تقريبًا: قواعد الحد الأدنى للعرض هي قواعد بكسلات، ولا كمية ضغط أو تعديل تستطيع إصلاح نقص البكسلات.</p>\n<h2 id=\"resolution-explained\">الدقة: DPI وPPI</h2>\n<p>الدقة تقول كم البكسلات مضغوطة: صورة 300 DPI تضع 300 بكسل في كل بوصة، بينما صورة 72 DPI تضع 72 فقط في نفس البوصة.</p>\n<p>على الشاشة، DPI لا يُحسب تقريبًا: متصفح يعرض البكسلات واحدًا واحدًا، فصورة 1000 بكسل تبدو نفسها عند 72 DPI وعند 300 DPI على شاشة. وفي الطباعة، DPI هو كل شيء: صورة 3000 بكسل عند 300 DPI تُطبع بعرض 10 بوصات، بينما نفس البكسلات عند 150 DPI تُطبع بعرض 20 بوصة بتفصيل أنعم بوضوح.</p>\n<p>DPI بيانات وصفية لا بكسلات: تغييره بـ<a href=\"/ar/taghyir-dpi-as-sura/\">مغير DPI الصور</a> يعيد كتابة رقم صغير في ترويسة الملف ويترك كل بكسل سليمًا، لهذا لا يفقد التغيير جودة.</p>\n<h2 id=\"file-size-explained\">حجم الملف: الوزن على القرص</h2>\n<p>يُقاس حجم الملف بالكيلوبايت أو الميغابايت، ويعتمد على الأبعاد والصيغة والضغط: صورة كبيرة محفوظة كـPNG دون ضغط قد تزن عشرة أضعاف نفس الصورة كـJPG.</p>\n<p>الضغط هو أكبر رافعة على حجم الملف: خفض جودة JPG من 90 إلى 70 قد يقلل الملف إلى النصف دون تغيير الأبعاد ولا DPI أبدًا. والصيغة مهمة أيضًا: PNG يحفظ الصور دون فقدان، فصور محفوظة كـPNG ثقيلة: وJPG وWebP يتخلصان من بيانات بالكاد تلاحظها العين، فهما أخف بكثير للصور.</p>\n<p>وحجم الملف يقرر نجاح الرفع وسرعة الصفحة: البوابات تحدده بالكيلوبايت، والمتصفحات تنزله عبر الشبكة، فملف ثقيل يفشل أو يتأخر.</p>\n<h2 id=\"how-they-relate\">كيف ترتبط الأرقام الثلاثة</h2>\n<p>الأبعاد تضع السقف لكل شيء آخر: صورة 4000 في 3000 تستطيع الطباعة كبيرة والعرض كبيرًا والضغط بطرق كثيرة، بينما صورة 400 في 300 لا تستطيع فعل أي من ذلك جيدًا.</p>\n<p>والدقة تترجم الأبعاد إلى حجم مادي: نفس صورة 3000 بكسل هي طباعة 10 بوصات عند 300 DPI وطباعة 20 بوصة عند 150 DPI، لأن DPI مجرد عامل تحويل. وحجم الملف هو تكلفة حفظ البكسلات: بكسلات أكثر تكلف بايتات أكثر، وضغط أقل يكلف بايتات أكثر أيضًا، فصورة كبيرة وقليلة الضغط هي أثقل ملف.</p>\n<p>فكر فيها كمثلث: الأبعاد هي كمية التفاصيل، والدقة هي كم هي مضغوطة بكثافة، وحجم الملف هو ما تدفعه للاحتفاظ بها.</p>\n<h2 id=\"big-file-small-dimensions\">لماذا قد يكون ملف كبير بأبعاد صغيرة</h2>\n<p>صورة صغيرة محفوظة كـPNG دون ضغط قد تزن عدة ميغابايت: صيغة PNG تحفظ كل بكسل بدقة، وصورة بها ضجيج لها معلومات دقيقة كثيرة لحفظها.</p>\n<p>لقطات الشاشة هي الحالة الكلاسيكية: لقطة 1200 في 800 محفوظة كـPNG قد تزن 2 MB، بينما نفس اللقطة محفوظة كـJPG تزن 200 KB، لأن JPG يتخلص من الضجيج. وهذا يفاجئ من يساوي حجم الملف بالجودة: PNG الثقيل ليس أفضل؛ إنه فقط أقل كفاءة في حفظ نفس البكسلات.</p>\n<p>وعندما ترفض بوابة ملفًا بسبب حجمه، راجع الصيغة أولًا: تحويل صورة PNG إلى JPG غالبًا يحل المشكلة دون لمس الأبعاد أبدًا.</p>\n<h2 id=\"small-file-huge-dimensions\">لماذا قد يكون ملف صغير بأبعاد ضخمة</h2>\n<p>صورة 6000 في 4000 محفوظة كـJPG بجودة منخفضة قد تزن أقل من 1 MB: الضغط القوي يتخلص من معظم التفاصيل الدقيقة ويترك شبكة كبيرة من بكسلات خشنة.</p>\n<p>الأبعاد تبدو مثيرة للإعجاب، لكن الصورة ليست كذلك: كبّر واختفى التفصيل، مستبدلًا بمصنوعات كتل وحواف ضبابية. ولهذا تراجع الأسواق الأبعاد ويراجع الناس الجودة: ملف قد يمر بحد البكسلات الأدنى وما زال يبدو فظيعًا عندما يكبّر مشترٍ.</p>\n<p>وللويب، هذا المزيج مفيد فعلًا: صورة رئيسية كبيرة ومضغوطة كثيرًا تملأ شاشة واسعة وتحمّل بسرعة، لأن من يراها لا يكبّر أبدًا بما يكفي لرؤية الضرر.</p>\n<h2 id=\"print-math\">حساب الطباعة: بكسلات مقسومة على DPI</h2>\n<p>حجم الطباعة يخرج من قسمة: بكسلات مقسومة على DPI تساوي بوصات: صورة 3000 بكسل عند 300 DPI تُطبع بعرض 10 بوصات، وعند 150 DPI تُطبع بعرض 20 بوصة.</p>\n<p>المعيار لطباعة الجودة هو 300 DPI: بتلك الكثافة، البكسلات المنفردة صغيرة جدًا لتراها العين على مسافة قراءة، فالطباعة تبدو ناعمة. ومطبوعات الصيغة الكبيرة تخفف المعيار: ملصق يُرى من مترين يبدو جيدًا عند 150 DPI، ولوحة إعلانية تُرى من الطريق قد تنخفض إلى 50 DPI أو أقل.</p>\n<p>وقبل إرسال ملف للطباعة، قم بالقسمة: إذا كانت النتيجة أصغر من الحجم الذي تحتاجه، احصل على ملف أكبر أو اقبل طباعة أصغر، لأن لا ضغط ولا تعديل يستطيع خلق بكسلات غير موجودة.</p>\n<h2 id=\"screen-math\">حساب الشاشة: بكسلات فقط، DPI لا يحسب</h2>\n<p>الشاشات لا تستخدم DPI كما تفعل الطابعات: متصفح يعرض صورة بكسلًا بكسلًا، فصورة 1000 بكسل تشغل 1000 بكسل شاشة بغض النظر عن ملصق DPI الخاص بها.</p>\n<p>لهذا تبدو صورة 72 DPI وصورة 300 DPI متطابقتين على موقع: قيمة DPI بيانات وصفية تتجاهلها المتصفحات ببساطة. وشاشات الكثافة العالية للهواتف تعقد الصورة قليلًا: هاتف بشاشة 2x يستخدم بكسلين ماديين لكل بكسل CSS، فصورة 1000 بكسل معروضة بعرض 500 بكسل CSS تبدو حادة على تلك الشاشة.</p>\n<p>والقاعدة العملية للويب بسيطة: طابق الأبعاد مع حجم العرض وانسَ DPI: صورة رئيسية معروضة بعرض 1200 بكسل يجب أن تكون بين 1200 و2400 بكسل عرضًا.</p>\n<h2 id=\"compression-and-file-size\">الضغط وحجم الملف</h2>\n<p>الضغط يغيّر حجم الملف دون تغيير الأبعاد ولا DPI: يعيد كتابة بيانات البكسلات بكفاءة أكبر ويتخلص من تفاصيل بالكاد تلاحظها العين.</p>\n<p>JPG وWebP صيغتان فاقدتان: كل حفظ يتخلص من تفصيل أكثر قليلًا: وPNG دون فقدان: يصغّر الملف دون التخلص من شيء، لهذا تبقى صور PNG ثقيلة. وضبط الجودة يتحكم في التوازن: JPG بجودة 90 يحافظ على كل التفاصيل المرئية تقريبًا، بينما نفس الصورة بجودة 50 تزن النصف ولها ضرر مرئي في المناطق المسطحة.</p>\n<p>استخدم <a href=\"/ar/\">ضاغط الصور</a> لإيجاد التوازن لصورك: يتيح لك رؤية النتيجة وحجم الملف معًا، فتستطيع التوقف عند النقطة التي يستحق فيها التوفير المقايضة.</p>\n<h2 id=\"choosing-dimensions-for-web\">كيف تختار الأبعاد للويب</h2>\n<p>للويب، طابق الأبعاد مع أكبر حجم ستُعرض فيه الصورة أبدًا: صورة معروضة بعرض 800 بكسل نادرًا تحتاج أكثر من 1600 بكسل في الملف.</p>\n<p>ملفات أكبر تحمّل أبطأ وتكلف مستخدمي الهاتف بيانات: صورة رئيسية 4000 بكسل معروضة بعرض 1200 بكسل تهدر ثلثي بكسلاتها في كل عرض. والمصغرات تحتاج أقل بكثير: صورة رمزية 200 بكسل محفوظة كملف 2000 بكسل أثقل بعشر مرات مما يلزم، والبكسلات الزائدة غير مرئية.</p>\n<p>والصور المتجاوبة تحل هذا كما ينبغي: تخدم ملفًا صغيرًا للهواتف وكبيرًا للحواسيب: لكن حتى دون ذلك، ضبط الملف على حجم العرض يوفر وقت تحميل في كل زيارة.</p>\n<h2 id=\"choosing-dimensions-for-print\">كيف تختار الأبعاد للطباعة</h2>\n<p>للطباعة، اعمل عكسيًا من الحجم المادي: اضرب البوصات التي تحتاجها في 300 للحصول على البكسلات التي تحتاجها، فطباعة 8 في 10 بوصات تحتاج 2400 في 3000 بكسل.</p>\n<p>راجع بيانات DPI الوصفية أيضًا: ملف بالبكسلات الصحيحة لكن ملصق 72 DPI سيُعامل كطباعة ضخمة من بعض البرامج، وسيخرج التصميم خطأ مع أن البكسلات صحيحة. وثبّت DPI صحيحًا بـ<a href=\"/ar/taghyir-dpi-as-sura/\">مغير DPI الصور</a> بعد تأكيد عدد البكسلات: الرقمان معًا يخبران المطبعة بالضبط ما تريد.</p>\n<p>وإذا لم تكفِ البكسلات، لا تكبّر أملًا أن يعمل: طباعة أصغر قليلًا بجودة كاملة تبدو أفضل من طباعة أكبر مصنوعة من بكسلات مخترعة.</p>\n<h2 id=\"choosing-dimensions-for-social\">كيف تختار الأبعاد لوسائل التواصل الاجتماعي والأسواق</h2>\n<p>المنصات الاجتماعية تقص بعدوانية، فالنسبة تهم بقدر عدد البكسلات: عمودي 1080 في 1350 يملأ خلاصة هاتف، بينما مربع 1080 في 1080 يبدو أصغر في نفس الخلاصة.</p>\n<p>الأسواق تريد صورًا كبيرة، مربعة أو شبه مربعة، بمساحة للتكبير: صورة منتج 2000 بكسل على خلفية بيضاء ترضي معظم الحدود الدنيا وتعطي المشترين تفاصيل للتكبير. ومصغرات الفيديو هي الاستثناء الذي يؤكد القاعدة: مصغرة 1280 في 720 صغيرة بالبكسلات لكنها يجب أن تُقرأ في لمحة، فالأشكال الجريئة تتغلب على التفاصيل الدقيقة.</p>\n<p>راجع كل صورة بـ<a href=\"/ar/fahis-abad-as-sura/\">فاحص أبعاد الصور</a> قبل رفعها إلى منصة جديدة: جدوله الدفعي وتحققانه الدنيا يكشفان الفشل قبل المنصة.</p>\n<h2 id=\"common-myths\">أساطير شائعة عن الأبعاد والدقة والحجم</h2>\n<p>الأسطورة الأولى أن DPI أعلى يجعل صورة ويب أوضح: ليس كذلك، لأن المتصفحات تتجاهل DPI: فقط الأبعاد بالبكسلات تقرر الحدة على الشاشة.</p>\n<p>والأسطورة الثانية أن ملفًا أكبر دائمًا صورة أفضل: PNG ثقيل وJPG خفيف قد يكون لهما بكسلات متطابقة، وJPG هو الملف الأفضل للويب في كل الحالات تقريبًا. والأسطورة الثالثة أن الميغابكسلات تقرر جودة الطباعة: إنها فقط نصف القصة؛ وحجم الطباعة وDPI يكملانها، وصورة 12 ميغابكسلًا مطبوعة بحجم ملصق قد تبدو ناعمة.</p>\n<p>والأسطورة الرابعة أن تغيير DPI يغيّر الصورة: يغيّر رقمًا في الترويسة لا بكسلًا واحدًا، وتبدو الصورة نفسها تمامًا على الشاشة قبل وبعد.</p>\n<h2 id=\"quick-reference\">مرجع سريع: أي رقم يهم أين</h2>\n<p>على الويب، الأبعاد تهم أكثر: طابق عرض البكسلات مع حجم العرض، وأبقِ حجم الملف منخفضًا بالضغط، وتجاهل DPI تمامًا.</p>\n<p>وفي الطباعة، الأبعاد وDPI يهمان معًا: اضرب بوصاتك في 300 للحصول على البكسلات التي تحتاجها ثم ثبّت ملصق DPI ليطابق. وللرفعات والبوابات، حجم الملف يهم أكثر: ملف يمر بحد البكسلات الأدنى قد يُرفض مع ذلك لوزنه كيلوبايتات كثيرة جدًا.</p>\n<p>ولمفردات مشتركة مع فريقك، تذكر التعريفات الثلاثة: الأبعاد هي عدد البكسلات، والدقة هي كثافة التغليف، وحجم الملف هو تكلفة الاحتفاظ بها.</p>\n<p>وللأدوات العملية، راجع <a href=\"/ar/blog/dalil-fahis-abad-as-suwar/\">دليل فاحص أبعاد الصور الكامل</a> والخطوات في <a href=\"/ar/blog/kayfiyya-fahs-abad-as-sura/\">كيف تفحص أبعاد صورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل تغيير DPI صورة يغيّر أبعادها؟","answer":"لا، DPI بيانات وصفية محفوظة في ترويسة الملف، وتغييره لا يضيف بكسلًا ولا يزيله: صورة 3000 في 2000 تبقى 3000 في 2000 سواء قال ملصق DPI 72 أو 300."},{"question":"لماذا ملف صورتي كبير جدًا مع أن أبعاده صغيرة؟","answer":"الصيغة والضغط يقرران الوزن أكثر من الأبعاد: صورة صغيرة محفوظة كـPNG دون ضغط قد تزن ميغابايتات، بينما نفس البكسلات محفوظة كـJPG تزن جزءًا من ذلك. وحوّل إلى JPG أو WebP لتصغير الملف."},{"question":"أي أبعاد أحتاج لطباعة A4 حادة؟","answer":"صفحة A4 نحو 8.3 في 11.7 بوصة، فعند 300 DPI تحتاج نحو 2500 في 3500 بكسل: ملف أصغر قد يُطبع في A4 مع ذلك، لكن التفصيل سيلطّف مع مد الطابعة للبكسلات."},{"question":"هل صورة 72 DPI ذات جودة سيئة؟","answer":"ليس بالضرورة: DPI يهم فقط للطباعة، وملصق 72 DPI لا يقول شيئًا عن البكسلات نفسها: صورة 4000 بكسل موسومة بـ72 DPI هي ملف عالي الجودة ببيانات وصفية خطأ."},{"question":"كيف تؤثر الأبعاد في سرعة تحميل صفحة؟","answer":"أبعاد أكبر تعني عادة ملفات أكبر، وملفات أكبر تستغرق تنزيلًا أطول: لكن العلاقة ليست ثابتة: صورة كبيرة ومضغوطة كثيرًا قد تحمّل أسرع من صورة أصغر محفوظة كـPNG دون ضغط."},{"question":"هل أستطيع زيادة أبعاد صورة دون فقدان جودة؟","answer":"ليس حقًا: التكبير يخترع بكسلات لم تُلتقط أبدًا، فالنتيجة أنعم دائمًا من أصل عالي الدقة حقيقي: مكبرات الذكاء الاصطناعي تعمل أفضل من تغيير الحجم البسيط، لكنها ما زالت تخمن تفاصيل."}];
